update scenarios set content = '{"characters": {"local": "un voyageur local"}, "start_node": "n1", "nodes": {"n1": {"speaker": "local", "text": "Need help finding something?", "text_fr": "Besoin d''aide pour trouver quelque chose ?", "choices": [{"text": "Yes, what''s the fastest route to Denver from here?", "text_fr": "Oui, quel est le chemin le plus rapide pour Denver d''ici ?", "next": "n2"}]}, "n2": {"speaker": "local", "text": "Take exit 45, it''ll save you almost an hour.", "text_fr": "Prenez la sortie 45, ça vous fera gagner presque une heure.", "choices": [{"text": "That''s a huge help, thank you! Is it well marked?", "text_fr": "C''est une aide précieuse, merci ! C''est bien indiqué ?", "next": "n3"}, {"text": "Perfect. Any good places to stop for gas along the way?", "text_fr": "Parfait. Des bonnes stations essence sur le trajet ?", "next": "n3b"}]}, "n3": {"speaker": "local", "text": "Yes, there''s a big blue sign right before the turn, you can''t miss it.", "text_fr": "Oui, il y a un grand panneau bleu juste avant le virage, impossible de le rater.", "choices": [{"text": "Great, thank you so much!", "text_fr": "Super, merci beaucoup !", "next": "end_directions"}]}, "n3b": {"speaker": "local", "text": "There''s a station right at exit 45, cheaper than the ones further down too.", "text_fr": "Il y a une station juste à la sortie 45, moins chère que celles plus loin en plus.", "choices": [{"text": "Perfect, that works out well then!", "text_fr": "Parfait, ça tombe bien alors !", "next": "end_gas"}]}, "end_directions": {"speaker": "local", "text": "No problem, safe travels out there!", "text_fr": "Pas de souci, bonne route !", "end": true, "ending_label": "Itinéraire optimisé 🗺️"}, "end_gas": {"speaker": "local", "text": "Exactly! Safe travels, and enjoy the trip.", "text_fr": "Exactement ! Bonne route, et profitez du voyage.", "end": true, "ending_label": "Itinéraire optimisé, plein fait au bon endroit ⛽🗺️"}}}'::jsonb
where title = 'Demander son chemin sur une aire d''autoroute';

update scenarios set content = '{"characters": {"guard": "un agent d''accueil"}, "start_node": "n1", "nodes": {"n1": {"speaker": "guard", "text": "Good morning, can I help?", "text_fr": "Bonjour, je peux vous aider ?", "choices": [{"text": "Yes, what time does the Tower of London open?", "text_fr": "Oui, à quelle heure ouvre la Tour de Londres ?", "next": "n2"}]}, "n2": {"speaker": "guard", "text": "It opens at 9am, but I''d recommend arriving early to avoid queues.", "text_fr": "Il ouvre à 9h, mais je recommande d''arriver tôt pour éviter les files d''attente.", "choices": [{"text": "Thanks for the tip, I''ll be there early.", "text_fr": "Merci pour le conseil, j''y serai tôt.", "next": "n3"}, {"text": "Is it better to book tickets online in advance?", "text_fr": "C''est mieux de réserver les billets en ligne à l''avance ?", "next": "n3b"}]}, "n3": {"speaker": "guard", "text": "Enjoy your visit!", "text_fr": "Bonne visite !", "choices": [{"text": "Thank you, have a great day!", "text_fr": "Merci, bonne journée !", "next": "end_info"}]}, "n3b": {"speaker": "guard", "text": "Definitely — it''s usually cheaper online too, and you can skip the ticket line entirely.", "text_fr": "C''est même souvent moins cher en ligne, et vous évitez complètement la file pour les billets.", "choices": [{"text": "Great, I''ll book tonight then. Thanks so much!", "text_fr": "Parfait, je réserve ce soir alors. Merci beaucoup !", "next": "end_online"}]}, "end_info": {"speaker": "guard", "text": "Enjoy your visit!", "text_fr": "Bonne visite !", "end": true, "ending_label": "Information obtenue 🏰"}, "end_online": {"speaker": "guard", "text": "Smart move. Enjoy the Tower tomorrow!", "text_fr": "Bonne idée. Profitez bien de la Tour demain !", "end": true, "ending_label": "Billets réservés en ligne, file évitée 🎟️🏰"}}}'::jsonb
where title = 'Demander l''heure d''ouverture d''un monument';
